    auto invalidUtf=t;invalidUtf.reference.ride=std::string(1,char(0xff));check(!validateReference(invalidUtf).valid(),"Invalid UTF-8 rejected");
    auto missingQuartile=t;missingQuartile.reference.q1=1;check(!validateReference(missingQuartile).valid(),"Unavailable quartile placeholder enforced");
    auto four=t;four.reference.hasQuartiles=true;four.reference.recordings.push_back(four.reference.recordings.back());auto& fourth=four.reference.recordings.back();fourth.recordingId="fourth";fourth.canonicalSha256=std::string(64,'d');fourth.exposure=13;four.reference.median=four.referenceExposure=11.5;four.reference.maximum=13;four.reference.q1=10.25;four.reference.q3=12.75;check(validateReference(four).valid(),"Exclusive quartiles match processor n4");
    auto conflict=t;conflict.referenceExposure=99;check(!validateReference(conflict).valid(),"Duplicated scalar mismatch rejected");
    auto constant=summarizeAxis(std::vector<double>(201,3),.1);near(constant.meanG,3,1e-12,"Constant mean");near(constant.mean1sMin,3,1e-12,"1s min");near(constant.mean10sMax,3,1e-12,"10s max");near(constant.maxRateGps,0,0,"Constant rate");std::vector<double> ramp;for(int i=0;i<200;++i)ramp.push_back(-5+i*.1);auto rs=summarizeAxis(ramp,.1);near(rs.maxRateGps,1,1e-12,"Signed ramp rate");near(rs.mean1sMin,-4.55,1e-12,"Signed zero-order 1s window");check(std::isnan(summarizeAxis({1,2},.1).mean1sMax),"Insufficient windows absent");
