    const auto directoryEnd=payload.find('\n',extension);std::istringstream directory(payload.substr(extension,directoryEnd-extension));std::string directoryTag;size_t originalCount;directory>>directoryTag>>originalCount;check(bool(directory)&&directoryTag=="EXTENSIONS","Read generated extension directory");
    write(bad,payload.substr(0,extension)+"EXTENSIONS "+std::to_string(originalCount+1)+"\n"+payload.substr(directoryEnd+1)+"AXIS_RATE_LIMITS 1 "+std::to_string(axisBlock.size())+"\n"+axisBlock);
    auto assessedLoaded=loaded;check(loadDesign(bad.string(),assessedLoaded,error)&&assessedLoaded.accepted(),"Parsed assessed rate receives actual passing half-step verification");near(assessedLoaded.request.limits.maxLateralRateGps,1000,0,"Configured axis limit persists exactly");check(std::isnan(assessedLoaded.request.limits.maxLongitudinalRateGps),"Unassessed axis stays unassessed");check(serializeReference(assessedLoaded.request.targets.reference)==serializeReference(t.reference),"Valid appended axis extension preserves typed evidence");
    auto assessedPath=folder/"typed-assessed.coaster";check(saveDesign(assessedLoaded,assessedPath.string(),error),"Verified assessed profile can be saved");Design assessedReplay;check(loadDesign(assessedPath.string(),assessedReplay,error)&&reportJson(assessedReplay)==reportJson(assessedLoaded),"Assessed profile save and full reverified replay agree");
    ComparisonHistory h;check(h.commit(d)&&!h.previous.available,"First accepted commit no previous");auto unchecked=d;unchecked.convergence={};check(!h.commit(unchecked)&&h.current.seed==d.request.seed&&!h.previous.available,"Unverified ride does not shift history");auto failed=d;failed.report.fail("TEST","test");check(!h.commit(failed)&&h.current.seed==d.request.seed&&!h.previous.available,"Failed commit does not shift history");auto second=d;second.request.seed=99;check(h.commit(second)&&h.current.seed==99&&h.previous.seed==d.request.seed,"Only accepted commit shifts comparison");auto lines=comparisonLines(second,&h.previous);check(std::any_of(lines.begin(),lines.end(),[](const auto& s){return s.find("uncertainty not quantified")!=std::string::npos;}),"Unquantified uncertainty visible");check(std::any_of(lines.begin(),lines.end(),[](const auto& s){return s.find("UNASSESSED")!=std::string::npos;}),"Unassessed axes visible");
    const auto legacyPath=std::filesystem::path(__FILE__).parent_path()/"fixtures/legacy-v021.coaster";auto retained=loaded;const auto legacyBytes=bytes(legacyPath);check(!loadDesign(legacyPath.string(),retained,error),"Older geometry schema is explicitly unsupported");check(error.find("unsupported schema")!=std::string::npos,"Old geometry is not silently reinterpreted");check(reportJson(retained)==reportJson(loaded)&&bytes(legacyPath)==legacyBytes,"Unsupported load preserves prior design and source bytes");
